    from public.reservations
    where id = p_reservation_id
      and reserved_for > now()
  );
$$;

create or replace function public.reservation_time_passed(p_reservation_id bigint)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from public.reservations
    where id = p_reservation_id
      and reserved_for <= now()
  );
$$;

create or replace function public.enforce_reservation_update()
returns trigger
language plpgsql
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if tg_op = 'INSERT' then
    if new.user_id <> (select auth.uid()) then
      raise exception 'reservations.user_id must match the authenticated user';
    end if;
    if new.reserved_for <= now() then
      raise exception 'reservation reserved_for must be in the future';
    end if;
    if new.status <> 'booked' then
      raise exception 'new reservations must have status booked';
    end if;
    return new;
  elsif tg_op = 'UPDATE' then
    if old.status <> 'booked' then
      raise exception 'reservation status is not booked';
    end if;
    if (select auth.uid()) is distinct from old.user_id then
      if not public.is_restaurant_staff(old.restaurant_id) then
        raise exception 'only the reservation owner or restaurant staff can update this reservation';
      end if;
    end if;
    if old.user_id = (select auth.uid()) then
      if new.user_id <> old.user_id or new.restaurant_id <> old.restaurant_id or new.party_size <> old.party_size then
        raise exception 'guests can only update reservation status';
      end if;
      if new.status <> 'cancelled' then
        raise exception 'guests can only cancel reservations';
      end if;
      if not public.reservation_in_future(old.id) then
        raise exception 'only future reservations can be cancelled';
      end if;
      return new;
    elsif public.is_restaurant_staff(old.restaurant_id) then
      if new.user_id <> old.user_id or new.restaurant_id <> old.restaurant_id or new.party_size <> old.party_size then
        raise exception 'staff can only update reservation status';
      end if;
      if new.status not in ('seated', 'no_show') then
        raise exception 'staff can only mark reservations as seated or no_show';
      end if;
      if not public.reservation_time_passed(old.id) then
        raise exception 'staff can only update past reservations';
      end if;
      return new;
    else
      raise exception 'only the reservation owner or restaurant staff can update this reservation';
    end if;
  end if;

  raise exception 'invalid trigger operation';
end;
$$;

create trigger enforce_reservation_update_trigger
before insert or update on public.reservations
for each row execute function public.enforce_reservation_update();

create policy restaurants_select_authenticated
on public.restaurants for select to authenticated
using (true);

create policy reservations_select_own_or_staff
on public.reservations for select to authenticated
using (user_id = (select auth.uid()) or public.is_restaurant_staff(restaurant_id));

create policy reservations_insert_own
on public.reservations for insert to authenticated
with check (user_id = (select auth.uid()) and reserved_for > now() and status = 'booked');

create policy reservations_update_own_or_staff
on public.reservations for update to authenticated
using (user_id = (select auth.uid()) or public.is_restaurant_staff(restaurant_id))
with check (user_id = (select auth.uid()) or public.is_restaurant_staff(restaurant_id));
