create or replace function public.prevent_stock_location_change()
returns trigger
language plpgsql
as $$
begin
  if auth.role() = 'service_role' then
    return old;
  end if;

  if tg_op = 'INSERT' then
    if not public.is_staff_at(new.location_id) then
      raise exception 'cannot add stock at a location where the user is not staff';
    end if;
    if public.location_frozen(new.location_id) then
      raise exception 'stock cannot be added while the location is frozen';
    end if;
    return new;
  end if;

  if tg_op = 'UPDATE' then
    if old.location_id <> new.location_id then
      raise exception 'stock location cannot be changed';
    end if;
    if not public.is_staff_at(old.location_id) then
      raise exception 'only staff can modify stock at this location';
    end if;
    if public.location_frozen(old.location_id) then
      raise exception 'stock cannot be changed while the location is frozen';
    end if;
    return new;
  end if;

  if tg_op = 'DELETE' then
    if not public.is_staff_at(old.location_id) then
      raise exception 'only staff can remove stock at this location';
    end if;
    if public.location_frozen(old.location_id) then
      raise exception 'stock cannot be removed while the location is frozen';
    end if;
    return old;
  end if;

  return old;
end;
$$;

