create or replace function public.page_protected(p_slug text)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(
    (select p.is_protected from public.pages p where p.slug = p_slug),
    false
  );
$$;

create or replace function public.enforce_page_update()
returns trigger
language plpgsql
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if old.is_protected and not public.is_editor() then
    raise exception 'only editors can modify protected pages';
  end if;

  if not old.is_protected and not public.is_editor() then
    if new.is_protected then
      raise exception 'only editors can protect a page';
    elsif new.updated_by is distinct from (select auth.uid()) then
      raise exception 'updated_by must be the editing user';
    end if;
  end if;

  return new;
end;
$$;

create or replace function public.enforce_revision_insert()
returns trigger
language plpgsql
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if not exists (
    select 1
    from public.pages p
    where p.slug = new.slug
      and (not p.is_protected or public.is_editor())
  ) then
    raise exception 'revision can only be added for editable pages';
  end if;

  if new.author_id is distinct from (select auth.uid()) then
    raise exception 'revision author must be the inserting user';
  end if;

  return new;
end;
$$;

create trigger pages_before_update
  before update on public.pages
  for each row execute function public.enforce_page_update();

create trigger page_revisions_before_insert
  before insert on public.page_revisions
  for each row execute function public.enforce_revision_insert();

create policy editors_select_authenticated
  on public.editors for select to authenticated
  using (true);

create policy pages_select_anyone
  on public.pages for select to anon, authenticated
  using (true);

create policy page_revisions_select_anyone
  on public.page_revisions for select to anon, authenticated
  using (true);

create policy pages_insert_unprotected_or_editor
  on public.pages for insert to authenticated
  with check (
    (not is_protected and updated_by = (select auth.uid()))
    or public.is_editor()
  );

create policy pages_update_own_unprotected_or_editor
  on public.pages for update to authenticated
  using (
    (not is_protected and updated_by = (select auth.uid()))
    or public.is_editor()
  )
  with check (
    (not is_protected and updated_by = (select auth.uid()))
    or public.is_editor()
  );

create policy page_revisions_insert_authenticated
  on public.page_revisions for insert to authenticated
  with check (author_id = (select auth.uid()));

