create or replace function public.paste_enforce_insert()
returns trigger
language plpgsql
as $$
begin
  if auth.uid() is null then
    if new.is_private then
      raise exception 'anonymous pastes cannot be private';
    end if;
    if new.author_id is not distinct from uuid('00000000-0000-0000-0000-000000000000') then
      raise exception 'anonymous pastes must have author_id null';
    end if;
  else
    if new.author_id is distinct from auth.uid() then
      raise exception 'paste author_id must match authenticated user';
    end if;
  end if;
  return new;
end;
$$;

