    from public.reviewers
    where user_id = (select auth.uid())
  );
$$;

create or replace function public.proposal_undecided(p_proposal_id bigint)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(
    (select p.status = 'submitted' or p.status = 'accepted' from public.proposals p where p.id = p_proposal_id),
    false
  );
$$;

create or replace function public.proposal_has_decision(p_proposal_id bigint)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from public.proposals p
    where p.id = p_proposal_id
      and p.status in ('rejected', 'accepted')
  );
$$;

create or replace function public.reviewers_guard()
returns trigger
language plpgsql
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if tg_op = 'INSERT' then
    if tg_table_name = 'public.reviewers' then
      raise exception 'reviewers table is immutable';
    end if;

    if tg_table_name = 'public.proposals' then
      if new.speaker_id <> (select auth.uid()) then
        raise exception 'proposals speaker must be the authenticated user';
      end if;
      if new.status <> 'submitted' then
        raise exception 'new proposals must be submitted';
      end if;
      return new;
    end if;

    if tg_table_name = 'public.reviews' then
      if new.reviewer_id <> (select auth.uid()) then
        raise exception 'reviews must be submitted by the authenticated user';
      end if;
      if not public.is_reviewer() then
        raise exception 'reviewer is not a reviewer';
      end if;
      if exists (
        select 1
        from public.reviews r
        where r.proposal_id = new.proposal_id
          and r.reviewer_id = new.reviewer_id
          and r.proposal_id <> new.proposal_id
      ) then
        raise exception 'review already exists';
      end if;
      if not public.proposal_undecided(new.proposal_id) then
        raise exception 'proposal decision is final';
      end if;
      if exists (
        select 1
        from public.reviews r
        where r.proposal_id = new.proposal_id
          and r.reviewer_id = new.reviewer_id
      ) then
        raise exception 'review already exists';
      end if;
      return new;
    end if;
  elsif tg_op = 'UPDATE' then
    if tg_table_name = 'public.reviewers' then
      raise exception 'reviewers table is immutable';
    end if;

    if tg_table_name = 'public.proposals' then
      if old.speaker_id <> (select auth.uid()) then
        raise exception 'proposals speaker cannot change';
      end if;
      if old.status in ('rejected', 'accepted') then
        raise exception 'proposal decision is final';
      end if;
      if new.status not in ('submitted', 'accepted', 'rejected') then
        raise exception 'invalid proposal status';
      end if;
      return new;
    end if;

    if tg_table_name = 'public.reviews' then
      if old.reviewer_id <> (select auth.uid()) then
        raise exception 'reviews reviewer cannot change';
      end if;
      if not public.proposal_undecided(old.proposal_id) then
        raise exception 'proposal decision is final';
      end if;
      if new.proposal_id <> old.proposal_id then
        raise exception 'review proposal cannot change';
      end if;
      if new.reviewer_id <> old.reviewer_id then
        raise exception 'review reviewer cannot change';
      end if;
      if new.score not between 1 and 5 then
        raise exception 'review score must be between 1 and 5';
      end if;
      return new;
    end if;
  end if;

  raise exception 'unknown trigger operation';
end;
$$;

create trigger reviewers_guard_trigger
before insert or update on public.reviewers
for each row execute function public.reviewers_guard();

create trigger proposals_guard_trigger
before insert or update on public.proposals
for each row execute function public.reviewers_guard();

create trigger reviews_guard_trigger
before insert or update on public.reviews
for each row execute function public.reviewers_guard();

