create or replace function public.enforce_permit_immutable_columns()
returns trigger
language plpgsql
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if tg_op = 'INSERT' then
    if new.revoked then
      raise exception 'new permits cannot be revoked';
    end if;
    if public.current_date_truncated() > new.valid_until then
      raise exception 'permit valid_until must be at least today';
    end if;
    if public.current_date_truncated() <= new.valid_until then
      if new.valid_until > public.current_date_truncated() + interval '365 days' then
        raise exception 'permit valid_until must be within 365 days from today';
      end if;
    end if;
    return new;
  end if;

  if tg_op = 'UPDATE' then
    if old.revoked is true and new.revoked is false then
      raise exception 'a revoked permit cannot be un-revoked';
    end if;
    if auth.uid() not in (select user_id from public.residents where unit_id = old.unit_id) then
      raise exception 'only the unit resident can update a permit';
