    if new.unit_id <> old.unit_id or new.plate <> old.plate then
      raise exception 'only the plate can be changed on a permit';
    end if;
    if new.valid_until <> old.valid_until or new.revoked <> old.revoked then
      raise exception 'validity and revocation status of a permit cannot be changed';
    end if;
    return new;
  end if;

